-- 0246_the_annual_appraisal_adds_itself_up
-- The Annual Appraisal in the library was a straight import of Thistle's paper form, with
-- everything the paper does wrong carried over: twenty one questions each scored out of
-- three, then FIVE SUMS THE MANAGER HAS TO DO BY HAND -- a total for Section A, one for
-- Section B, one for Section C, an overall, and then reading that overall off a band table
-- and picking the matching option from a dropdown. Five arithmetic steps at the end of a
-- long meeting, every one of which can be got wrong, and nobody reading the file a year
-- later would ever know it had been.
--
-- Phil, 2026-09-08: "there is a scoring system on there, lets make this add up
-- automatically." So the four totals and the band are now computed fields: they are worked
-- out from the answers, shown read only as they are filled in, and RECOMPUTED ON THE
-- SERVER before the Evidence is written, so the score stored is what the schema says it is
-- rather than whatever the browser posted.
--
-- N/A IS NOT COUNTED, BOTH WAYS (Phil, 2026-09-08: "score out of what applied"). Thistle's
-- own instruction is "if the answer is not applicable please do not include question points
-- in the final score", but its band table is written as though all twenty one always apply.
-- Five N/As cap the score at 48, and 48 out of 63 sits below the top band -- so a person
-- could do everything asked of them perfectly and still be unable to reach "Exceeding".
-- The band is therefore taken as a share of the points ACTUALLY AVAILABLE, and the score
-- is stored as "48 of 48" so the denominator is never hidden.
--
-- THE SECTIONS ARE REAL SECTIONS. The import had all fifty two fields in one block called
-- "Details", with the section headings glued onto the front of the first question's label
-- ("Section A: Professional Attributes\n\nUnderstanding care objectives"). Each section is
-- now a section, with its total at the foot of it.
--
-- DROPPED as givens, as on every other form: Name, Region and Completed By. The record
-- knows them and the Evidence stamps who submitted it and when.
--
-- CHANGED FROM THE PAPER, worth saying out loud:
--   * The manager's signature is required and the employee's is not. The paper has it the
--     other way round, which cannot be right: the manager is the one completing the form,
--     and the employee may not be sitting there to sign it.
--   * Manager comments are required, employee comments are not.
--   * "Sickness / Unauthorised Lave" is spelt Leave.
--
-- Replaced IN PLACE at version 1 across the master template and both company copies. No
-- Annual Appraisal evidence exists anywhere; the guard enforces that rather than trusting
-- this note.
-- Applied to the becarecompliant project ONLY (ref bgrtcvyjuwopunpnudeu).

do $$
declare
  v_schema jsonb := '{"schemaVersion": 1, "sections": [{"id": "appraisal", "title": "The appraisal", "fields": [{"key": "appraisal_date", "type": "date", "label": "Date of appraisal", "required": true}]}, {"id": "section_a", "title": "Section A: Professional Attributes", "fields": [{"key": "a_care_objectives", "type": "single_select", "label": "Understanding care objectives", "required": true, "options": [{"value": "3", "label": "3"}, {"value": "2", "label": "2"}, {"value": "1", "label": "1"}, {"value": "0", "label": "0"}, {"value": "na", "label": "N/A"}]}, {"key": "a_care_objectives_comments", "type": "long_text", "label": "Understanding care objectives - comments", "validation": {"maxLength": 2000}}, {"key": "a_work_environment", "type": "single_select", "label": "Understanding of work environment", "required": true, "options": [{"value": "3", "label": "3"}, {"value": "2", "label": "2"}, {"value": "1", "label": "1"}, {"value": "0", "label": "0"}, {"value": "na", "label": "N/A"}]}, {"key": "a_work_environment_comments", "type": "long_text", "label": "Understanding of work environment - comments", "validation": {"maxLength": 2000}}, {"key": "a_problem_solving", "type": "single_select", "label": "Problem solving", "required": true, "options": [{"value": "3", "label": "3"}, {"value": "2", "label": "2"}, {"value": "1", "label": "1"}, {"value": "0", "label": "0"}, {"value": "na", "label": "N/A"}]}, {"key": "a_problem_solving_comments", "type": "long_text", "label": "Problem solving - comments", "validation": {"maxLength": 2000}}, {"key": "a_written_communication", "type": "single_select", "label": "Written communication", "required": true, "options": [{"value": "3", "label": "3"}, {"value": "2", "label": "2"}, {"value": "1", "label": "1"}, {"value": "0", "label": "0"}, {"value": "na", "label": "N/A"}]}, {"key": "a_written_communication_comments", "type": "long_text", "label": "Written communication - comments", "validation": {"maxLength": 2000}}, {"key": "a_oral_communication", "type": "single_select", "label": "Oral communication", "required": true, "options": [{"value": "3", "label": "3"}, {"value": "2", "label": "2"}, {"value": "1", "label": "1"}, {"value": "0", "label": "0"}, {"value": "na", "label": "N/A"}]}, {"key": "a_oral_communication_comments", "type": "long_text", "label": "Oral communication - comments", "validation": {"maxLength": 2000}}, {"key": "a_service_users", "type": "single_select", "label": "Relationship and attitude towards service users", "required": true, "options": [{"value": "3", "label": "3"}, {"value": "2", "label": "2"}, {"value": "1", "label": "1"}, {"value": "0", "label": "0"}, {"value": "na", "label": "N/A"}]}, {"key": "a_service_users_comments", "type": "long_text", "label": "Relationship and attitude towards service users - comments", "validation": {"maxLength": 2000}}, {"key": "a_colleagues", "type": "single_select", "label": "Relationship and attitude towards colleagues", "required": true, "options": [{"value": "3", "label": "3"}, {"value": "2", "label": "2"}, {"value": "1", "label": "1"}, {"value": "0", "label": "0"}, {"value": "na", "label": "N/A"}]}, {"key": "a_colleagues_comments", "type": "long_text", "label": "Relationship and attitude towards colleagues - comments", "validation": {"maxLength": 2000}}, {"key": "a_stakeholders", "type": "single_select", "label": "Relationship and attitude towards external stakeholders", "required": true, "options": [{"value": "3", "label": "3"}, {"value": "2", "label": "2"}, {"value": "1", "label": "1"}, {"value": "0", "label": "0"}, {"value": "na", "label": "N/A"}]}, {"key": "a_stakeholders_comments", "type": "long_text", "label": "Relationship and attitude towards external stakeholders - comments", "validation": {"maxLength": 2000}}, {"key": "a_line_manager", "type": "single_select", "label": "Relationship and attitude towards line manager", "required": true, "options": [{"value": "3", "label": "3"}, {"value": "2", "label": "2"}, {"value": "1", "label": "1"}, {"value": "0", "label": "0"}, {"value": "na", "label": "N/A"}]}, {"key": "a_line_manager_comments", "type": "long_text", "label": "Relationship and attitude towards line manager - comments", "validation": {"maxLength": 2000}}, {"key": "a_procedures", "type": "single_select", "label": "Ability to follow procedure and instructions", "required": true, "options": [{"value": "3", "label": "3"}, {"value": "2", "label": "2"}, {"value": "1", "label": "1"}, {"value": "0", "label": "0"}, {"value": "na", "label": "N/A"}]}, {"key": "a_procedures_comments", "type": "long_text", "label": "Ability to follow procedure and instructions - comments", "validation": {"maxLength": 2000}}, {"key": "section_a_total", "type": "score_total", "label": "Section A total", "sum": ["a_care_objectives", "a_work_environment", "a_problem_solving", "a_written_communication", "a_oral_communication", "a_service_users", "a_colleagues", "a_stakeholders", "a_line_manager", "a_procedures"], "pointsPerQuestion": 3}], "description": "Each question is scored out of 3. Anything marked N/A is left out of both the score and the total, so nobody is marked down for something that did not apply."}, {"id": "section_b", "title": "Section B: Personal Attributes", "fields": [{"key": "b_punctuality", "type": "single_select", "label": "Punctuality", "required": true, "options": [{"value": "3", "label": "3"}, {"value": "2", "label": "2"}, {"value": "1", "label": "1"}, {"value": "0", "label": "0"}, {"value": "na", "label": "N/A"}]}, {"key": "b_punctuality_comments", "type": "long_text", "label": "Punctuality - comments", "validation": {"maxLength": 2000}}, {"key": "b_sickness", "type": "single_select", "label": "Sickness and unauthorised leave", "required": true, "options": [{"value": "3", "label": "3"}, {"value": "2", "label": "2"}, {"value": "1", "label": "1"}, {"value": "0", "label": "0"}, {"value": "na", "label": "N/A"}]}, {"key": "b_sickness_comments", "type": "long_text", "label": "Sickness and unauthorised leave - comments", "validation": {"maxLength": 2000}}, {"key": "b_reliability_cooperation", "type": "single_select", "label": "Reliability and cooperation", "required": true, "options": [{"value": "3", "label": "3"}, {"value": "2", "label": "2"}, {"value": "1", "label": "1"}, {"value": "0", "label": "0"}, {"value": "na", "label": "N/A"}]}, {"key": "b_reliability_cooperation_comments", "type": "long_text", "label": "Reliability and cooperation - comments", "validation": {"maxLength": 2000}}, {"key": "b_appearance", "type": "single_select", "label": "Appearance", "required": true, "options": [{"value": "3", "label": "3"}, {"value": "2", "label": "2"}, {"value": "1", "label": "1"}, {"value": "0", "label": "0"}, {"value": "na", "label": "N/A"}]}, {"key": "b_appearance_comments", "type": "long_text", "label": "Appearance - comments", "validation": {"maxLength": 2000}}, {"key": "b_organisational_skills", "type": "single_select", "label": "Organisational skills", "required": true, "options": [{"value": "3", "label": "3"}, {"value": "2", "label": "2"}, {"value": "1", "label": "1"}, {"value": "0", "label": "0"}, {"value": "na", "label": "N/A"}]}, {"key": "b_organisational_skills_comments", "type": "long_text", "label": "Organisational skills - comments", "validation": {"maxLength": 2000}}, {"key": "b_under_pressure", "type": "single_select", "label": "Ability to cope under pressure", "required": true, "options": [{"value": "3", "label": "3"}, {"value": "2", "label": "2"}, {"value": "1", "label": "1"}, {"value": "0", "label": "0"}, {"value": "na", "label": "N/A"}]}, {"key": "b_under_pressure_comments", "type": "long_text", "label": "Ability to cope under pressure - comments", "validation": {"maxLength": 2000}}, {"key": "section_b_total", "type": "score_total", "label": "Section B total", "sum": ["b_punctuality", "b_sickness", "b_reliability_cooperation", "b_appearance", "b_organisational_skills", "b_under_pressure"], "pointsPerQuestion": 3}]}, {"id": "section_c", "title": "Section C: Practical Skills", "fields": [{"key": "c_quality_of_work", "type": "single_select", "label": "Quality of work provided", "required": true, "options": [{"value": "3", "label": "3"}, {"value": "2", "label": "2"}, {"value": "1", "label": "1"}, {"value": "0", "label": "0"}, {"value": "na", "label": "N/A"}]}, {"key": "c_quality_of_work_comments", "type": "long_text", "label": "Quality of work provided - comments", "validation": {"maxLength": 2000}}, {"key": "c_ability_in_role", "type": "single_select", "label": "Level of ability in role", "required": true, "options": [{"value": "3", "label": "3"}, {"value": "2", "label": "2"}, {"value": "1", "label": "1"}, {"value": "0", "label": "0"}, {"value": "na", "label": "N/A"}]}, {"key": "c_ability_in_role_comments", "type": "long_text", "label": "Level of ability in role - comments", "validation": {"maxLength": 2000}}, {"key": "c_reliability", "type": "single_select", "label": "Reliability", "required": true, "options": [{"value": "3", "label": "3"}, {"value": "2", "label": "2"}, {"value": "1", "label": "1"}, {"value": "0", "label": "0"}, {"value": "na", "label": "N/A"}]}, {"key": "c_reliability_comments", "type": "long_text", "label": "Reliability - comments", "validation": {"maxLength": 2000}}, {"key": "c_initiative", "type": "single_select", "label": "Ability to use own initiative", "required": true, "options": [{"value": "3", "label": "3"}, {"value": "2", "label": "2"}, {"value": "1", "label": "1"}, {"value": "0", "label": "0"}, {"value": "na", "label": "N/A"}]}, {"key": "c_initiative_comments", "type": "long_text", "label": "Ability to use own initiative - comments", "validation": {"maxLength": 2000}}, {"key": "c_effort", "type": "single_select", "label": "Effort and determination", "required": true, "options": [{"value": "3", "label": "3"}, {"value": "2", "label": "2"}, {"value": "1", "label": "1"}, {"value": "0", "label": "0"}, {"value": "na", "label": "N/A"}]}, {"key": "c_effort_comments", "type": "long_text", "label": "Effort and determination - comments", "validation": {"maxLength": 2000}}, {"key": "section_c_total", "type": "score_total", "label": "Section C total", "sum": ["c_quality_of_work", "c_ability_in_role", "c_reliability", "c_initiative", "c_effort"], "pointsPerQuestion": 3}]}, {"id": "score", "title": "Overall score", "fields": [{"key": "overall_total", "type": "score_total", "label": "Overall appraisal score", "sum": ["a_care_objectives", "a_work_environment", "a_problem_solving", "a_written_communication", "a_oral_communication", "a_service_users", "a_colleagues", "a_stakeholders", "a_line_manager", "a_procedures", "b_punctuality", "b_sickness", "b_reliability_cooperation", "b_appearance", "b_organisational_skills", "b_under_pressure", "c_quality_of_work", "c_ability_in_role", "c_reliability", "c_initiative", "c_effort"], "pointsPerQuestion": 3}, {"key": "overall_band", "type": "score_band", "label": "Overall annual appraisal rating", "from": ["overall_total"], "fullScale": 63, "pointsPerQuestion": 3, "bands": [{"upTo": 15, "label": "Unsatisfactory"}, {"upTo": 30, "label": "Improvement needed"}, {"upTo": 50, "label": "Achieving required standard"}, {"upTo": 63, "label": "Exceeding required standard"}], "help": "Worked out from the points actually available, so N/A answers do not cap the rating."}]}, {"id": "sign_off", "title": "Comments and sign off", "fields": [{"key": "employee_comments", "type": "long_text", "label": "Employee comments", "validation": {"maxLength": 4000}}, {"key": "manager_comments", "type": "long_text", "label": "Manager comments", "required": true, "validation": {"maxLength": 4000}}, {"key": "manager_signature", "type": "signature", "label": "Manager''s declaration", "required": true, "help": "I confirm that this is an accurate and true record of the annual appraisal."}, {"key": "employee_signature", "type": "signature", "label": "Employee signature"}]}]}'::jsonb;
  v_blocked int;
begin
  select count(*) into v_blocked
    from public.evidence e
    join public.form_versions fv on fv.id = e.form_version_id
    join public.forms f on f.id = fv.form_id
   where f.key = 'annual_appraisal_acme';

  if v_blocked > 0 then
    raise exception 'Annual Appraisal has % pieces of evidence against it; publish a new version instead of replacing v1', v_blocked;
  end if;

  update public.form_templates
     set schema = v_schema,
         name = 'Annual Appraisal',
         updated_at = now()
   where key = 'annual_appraisal_acme';

  update public.form_versions fv
     set schema = v_schema
    from public.forms f
   where f.id = fv.form_id
     and f.key = 'annual_appraisal_acme'
     and fv.version = 1;
end $$;
